def solve(expr):
    def apply_op(op, a, b):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            return a // b

    def evaluate(expression):
        stack = []
        operator = '+'
        num = 0
        for i, char in enumerate(expression):
            if char.isdigit():
                num = num * 10 + int(char)
            if char in '+-*/' or i == len(expression) - 1:
                if operator == '+':
                    stack.append(num)
                elif operator == '-':
                    stack.append(-num)
                elif operator == '*':
                    stack.append(stack.pop() * num)
                elif operator == '/':
                    stack.append(stack.pop() // num)
                operator = char
                num = 0
        return sum(stack)

    return evaluate(expr)

# Example usage:
# print(solve("3+2*2"))  # Output: 7
# print(solve(" 3/2 "))  # Output: 1
# print(solve(" 3+5 / 2 "))  # Output: 5
